method get_positive(l: seq<int>) returns (result: seq<int>)
    requires l != null
    ensures forall i :: 0 <= i < |result| ==> result[i] > 0
    ensures |result| == CountPositives(l)
{
    var temp: seq<int> := [];
    var i: int := 0;
    while i < |l|
        invariant 0 <= i <= |l|
        invariant forall j :: 0 <= j < |temp| ==> temp[j] > 0
        invariant |temp| == CountPositives(slice(l, 0, i))
    {
        if l[i] > 0 {
            temp := temp + [l[i]];
        }
        i := i + 1;
    }
    result := temp;
}

method CountPositives(l: seq<int>) returns (count: int)
    requires l != null
    ensures count == |{ x | x <- l, x > 0 }|
{
    count := 0;
    var i: int := 0;
    while i < |l|
        invariant 0 <= i <= |l|
        invariant count == |{ x | j <- slice(l, 0, i), x == j && x > 0 }|
    {
        if l[i] > 0 {
            count := count + 1;
        }
        i := i + 1;
    }
}
